import { styled } from '@hexa-ui/theme';

export const StyledBreadcrumbContainer = styled('div', {
  display: 'flex',
  alignItems: 'center',
  flexWrap: 'wrap',
  gap: '4px',
  paddingLeft: '24px',
  paddingRight: '24px',
  marginLeft: '-24px',
  marginRight: '-24px',
});

export const StyledChip = styled('div', {
  display: 'inline-flex',
  alignItems: 'center',
  gap: '4px',
  padding: '4px 10px',
  border: '1px solid #D9D9D9',
  borderRadius: '1rem',
  backgroundColor: '$surface_primary',
  fontSize: '$2',
  fontWeight: '$medium',
  fontFamily: '$paragraph',
  color: '#141414',
  lineHeight: '20px',
  whiteSpace: 'nowrap',
  cursor: 'default',

  variants: {
    isHighlighted: {
      true: {
        backgroundColor: '#FFF1C2',
        borderColor: '#FFF1C2',
      },
    },
    isInteractive: {
      true: {
        cursor: 'pointer',
        '&:hover': { opacity: 0.8 },
      },
    },
  },
});

export const StyledChipLabel = styled('span', {
  overflow: 'hidden',
  textOverflow: 'ellipsis',
  whiteSpace: 'nowrap',
  maxWidth: '200px',
});

export const StyledCloseButton = styled('button', {
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
  padding: '0',
  background: 'white',
  border: 'none',
  cursor: 'pointer',
  color: '#141414',
  borderRadius: '50%',
  width: '16px',
  height: '16px',

  svg: {
    width: '10px',
    height: '10px',
  },

  '&:hover': {
    backgroundColor: 'rgba(20, 20, 20, 0.08)',
  },

  '&:focus-visible': {
    outline: '2px solid #141414',
    outlineOffset: '2px',
  },
});

export const StyledSeparator = styled('span', {
  display: 'inline-flex',
  alignItems: 'center',
  padding: '0 4px',
  userSelect: 'none',
});
